def find_zero_regions(grid):
    """Find connected regions of 0s"""
    visited = set()
    regions = []

    for r in range(len(grid)):
        for c in range(len(grid[0])):
            if grid[r][c] == 0 and (r,c) not in visited:
                region = []
                queue = deque([(r,c)])
                while queue:
                    curr = queue.popleft()
                    if curr in visited:
                        continue
                    visited.add(curr)
                    region.append(curr)
                    rr, cc = curr
                    for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                        nn = (rr+dr, cc+dc)
                        if 0 <= nn[0] < len(grid) and 0 <= nn[1] < len(grid[0]):
