# Check if stayed 0 cells are "inside" surrounded by other 0s
def get_4_neighbours(grid, r, c):
    neighs = []
    for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
        nr, nc = r+dr, c+dc
        if 0 <= nr < len(grid) and 0 <= nc < len(grid[0]):
            neighs.append((grid[nr][nc], (nr, nc)))
    return neighs

for pos in stayed_zero:
    neighs = get_4_neighbours(inp1, pos[0], pos[1])
    all_zeros = all(v == 0 for v, _ in neighs)
    print(f"{pos}: neighbours = {[v for v,_ in neighs]}, all_zeros={all_zeros}")
